/// `withCount('contacts')` of labels: their contacts, soft-deleted ones left out.
async fn contacts_counts<C: ConnectionTrait>(db: &C, label_ids: Vec<Id>) -> ApiResult<HashMap<Id, i64>> {
    let mut out = HashMap::new();
    if label_ids.is_empty() {
        return Ok(out);
    }
    let rows = contact_label::Entity::find()
        .filter(contact_label::Column::LabelId.is_in(label_ids))
        .inner_join(contacts::Entity)
        .filter(contacts::Column::DeletedAt.is_null())
        .all(db)
        .await?;
    for r in rows {
        *out.entry(r.label_id).or_insert(0) += 1;
    }
    Ok(out)
}

/// `withCount('posts')` of tags (Q6: every post of the vault).
async fn posts_counts<C: ConnectionTrait>(db: &C, tag_ids: Vec<Id>) -> ApiResult<HashMap<Id, i64>> {
    let mut out = HashMap::new();
    if tag_ids.is_empty() {
        return Ok(out);
    }
    let rows = post_tag::Entity::find()
        .filter(post_tag::Column::TagId.is_in(tag_ids))
        .inner_join(posts::Entity)
        .all(db)
        .await?;
    for r in rows {
        *out.entry(r.tag_id).or_insert(0) += 1;
    }
    Ok(out)
}

/// The types of each category, by `position` (`dtoLifeEventCategory`).
async fn life_event_types_of<C: ConnectionTrait>(
    db: &C,
    category_ids: Vec<Id>,
) -> ApiResult<HashMap<Id, Vec<LifeEventType>>> {
    let mut out: HashMap<Id, Vec<LifeEventType>> = HashMap::new();
    if category_ids.is_empty() {
        return Ok(out);
    }
    let rows = life_event_types::Entity::find()
        .filter(life_event_types::Column::LifeEventCategoryId.is_in(category_ids))
        .order_by_asc(life_event_types::Column::Position)
        .order_by_asc(life_event_types::Column::Id)
        .all(db)
        .await?;
    for t in rows {
        out.entry(t.life_event_category_id).or_default().push(t.into());
    }
    Ok(out)
}

async fn life_event_category_with_types<C: ConnectionTrait>(
    db: &C,
    c: life_event_categories::Model,
) -> ApiResult<LifeEventCategory> {
    let types = life_event_types_of(db, vec![c.id]).await?.remove(&c.id).unwrap_or_default();
    Ok(LifeEventCategory::new(c, types))
}

