// ---------------------------------------------------------------- validation

/// A required string: trimmed, `required`, at most `max` characters.
fn required(v: &mut Validator, field: &str, value: Option<String>, max: usize) -> Option<String> {
    let value = clean(value);
    if v.required(field, &value) {
        v.max_len(field, value.as_deref(), max);
    }
    value
}

/// A string a PATCH may leave out: `None` when absent. Sent, it is trimmed
/// and must not be blank (`rule` fails: `required`, or `string` for rules
/// without `required`) nor longer than `max`.
fn sent(v: &mut Validator, field: &str, value: Option<String>, rule: &str, max: usize) -> Option<String> {
    let value = clean(Some(value?));
    match value.as_deref() {
        None => v.fail(field, rule, &[]),
        Some(s) => v.max_len(field, Some(s), max),
    }
    value
}

/// A new `position`: an integer from 1.
fn position(v: &mut Validator, position: Option<i64>) -> Option<i32> {
    v.between("position", position, 1, i64::from(i32::MAX));
    position.and_then(|p| i32::try_from(p).ok())
}

#[utoipa::path(
    get,
    path = "/vaults/{vault_id}/labels",
    operation_id = "listVaultLabels",
    tag = "Vaults",
    summary = "List the vault's labels, by name",
    params(("vault_id" = uuid::Uuid, Path)),
    responses((status = 200, description = "Labels with `contacts_count`, sorted by name (locale collation).", body = LabelList), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`).")),
    extensions(("x-permission" = json!("vault:view")), ("x-inventory" = json!(["R173"])), ("x-services" = json!([])))
)]
pub async fn list_vault_labels(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path(vault_id): Path<Uuid>,
) -> ApiResult<Json<LabelList>> {
    access::vault(&state, &id, vault_id, crate::domains::base::VaultPermission::View).await?;
    let rows = labels::Entity::find()
        .filter(labels::Column::VaultId.eq(vault_id))
        .order_by_asc(labels::Column::Id)
        .all(&state.db)
        .await?;
    let counts = contacts_counts(&state.db, rows.iter().map(|l| l.id).collect()).await?;
    let mut data: Vec<Label> = rows
        .into_iter()
        .map(|l| {
            let count = counts.get(&l.id).copied().unwrap_or(0);
            Label::new(l, count)
        })
        .collect();
    crate::text::sort_by_collator(&mut data, |l| l.name.clone());
    Ok(Json(LabelList { data }))
}

#[utoipa::path(
    post,
    path = "/vaults/{vault_id}/labels",
    operation_id = "createVaultLabel",
    tag = "Vaults",
    summary = "Create a label",
    params(("vault_id" = uuid::Uuid, Path)),
    request_body = LabelCreate,
    responses((status = 201, description = "The created label.", body = Label), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`)."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("vault:edit")), ("x-inventory" = json!(["R180"])), ("x-services" = json!(["CreateLabel"])))
)]
pub async fn create_vault_label(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path(vault_id): Path<Uuid>,
    Json(body): Json<LabelCreate>,
) -> ApiResult<(StatusCode, Json<Label>)> {
    access::vault(&state, &id, vault_id, crate::domains::base::VaultPermission::Edit).await?;
    let mut v = Validator::new();
    let name = required(&mut v, "name", body.name, 255);
    let description = clean(body.description);
    v.max_len("description", description.as_deref(), 65535);
    let bg_color = clean(body.bg_color);
    v.max_len("bg_color", bg_color.as_deref(), 255);
    let text_color = clean(body.text_color);
    v.max_len("text_color", text_color.as_deref(), 255);
    v.finish()?;
    let label = CreateLabel {
        account_id: id.user.account_id,
        author_id: id.user.id,
        vault_id,
        name: name.unwrap(),
        description,
        bg_color,
        text_color,
    }
    .execute(&state.db)
    .await?;
    Ok((StatusCode::CREATED, Json(Label::new(label, 0))))
}

