#[utoipa::path(
    patch,
    path = "/vaults/{vault_id}/mood-tracking-parameters/{mood_tracking_parameter_id}",
    operation_id = "updateVaultMoodTrackingParameter",
    tag = "Vaults",
    summary = "Edit or move a mood tracking parameter",
    params(("vault_id" = uuid::Uuid, Path), ("mood_tracking_parameter_id" = i64, Path)),
    request_body = MoodTrackingParameterUpdate,
    responses((status = 200, description = "The updated parameter.", body = MoodTrackingParameter), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`)."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("vault:manage")), ("x-inventory" = json!(["R192", "R193"])), ("x-services" = json!(["UpdateMoodTrackingParameter", "UpdateMoodTrackingParameterPosition"])))
)]
pub async fn update_vault_mood_tracking_parameter(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, mood_tracking_parameter_id)): Path<(Uuid, Id)>,
    Json(body): Json<MoodTrackingParameterUpdate>,
) -> ApiResult<Json<MoodTrackingParameter>> {
    access::vault(&state, &id, vault_id, crate::domains::base::VaultPermission::Manage).await?;
    let mut parameter = find_mood_tracking_parameter(&state, vault_id, mood_tracking_parameter_id).await?;
    let mut v = Validator::new();
    let label = sent(&mut v, "label", body.label, "required", 255);
    let hex_color = sent(&mut v, "hex_color", body.hex_color, "required", 255);
    let new_position = position(&mut v, body.position);
    v.finish()?;
    let (account_id, author_id) = (id.user.account_id, id.user.id);
    let tx = state.db.begin().await?;
    if label.is_some() || hex_color.is_some() {
        // Left out, the label is the one the PHP form sent back: the stored
        // label, else the translated key (the model's `label` accessor).
        let label = label
            .or_else(|| parameter.label.clone())
            .or_else(|| {
                parameter.label_translation_key.as_deref().map(|k| crate::i18n::t(&crate::i18n::current(), k, &[]))
            })
            .unwrap_or_default();
        parameter = UpdateMoodTrackingParameter {
            account_id,
            author_id,
            vault_id,
            mood_tracking_parameter_id: parameter.id,
            label,
            hex_color: hex_color.unwrap_or(parameter.hex_color),
        }
        .execute(&tx)
        .await?;
    }
    if let Some(new_position) = new_position {
        parameter = UpdateMoodTrackingParameterPosition {
            account_id,
            author_id,
            vault_id,
            mood_tracking_parameter_id: parameter.id,
            new_position,
        }
        .execute(&tx)
        .await?;
    }
    tx.commit().await?;
    Ok(Json(parameter.into()))
}

