#[utoipa::path(
    patch,
    path = "/vaults/{vault_id}/life-event-categories/{life_event_category_id}",
    operation_id = "updateVaultLifeEventCategory",
    tag = "Vaults",
    summary = "Rename or move a life event category",
    params(("vault_id" = uuid::Uuid, Path), ("life_event_category_id" = i64, Path)),
    request_body = LifeEventCategoryUpdate,
    responses((status = 200, description = "The updated category.", body = LifeEventCategory), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`)."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("vault:manage")), ("x-inventory" = json!(["R196", "R198"])), ("x-services" = json!(["UpdateLifeEventCategory", "UpdateLifeEventCategoryPosition"])))
)]
pub async fn update_vault_life_event_category(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, life_event_category_id)): Path<(Uuid, Id)>,
    Json(body): Json<LifeEventCategoryUpdate>,
) -> ApiResult<Json<LifeEventCategory>> {
    access::vault(&state, &id, vault_id, crate::domains::base::VaultPermission::Manage).await?;
    let mut category = find_life_event_category(&state, vault_id, life_event_category_id).await?;
    let mut v = Validator::new();
    let label = sent(&mut v, "label", body.label, "required", 255);
    let new_position = position(&mut v, body.position);
    v.finish()?;
    let (account_id, author_id) = (id.user.account_id, id.user.id);
    let tx = state.db.begin().await?;
    if let Some(label) = label {
        category = UpdateLifeEventCategory {
            account_id,
            vault_id,
            author_id,
            life_event_category_id: category.id,
            label,
            can_be_deleted: category.can_be_deleted,
        }
        .execute(&tx)
        .await?;
    }
    if let Some(new_position) = new_position {
        category = UpdateLifeEventCategoryPosition {
            account_id,
            author_id,
            vault_id,
            life_event_category_id: category.id,
            new_position,
        }
        .execute(&tx)
        .await?;
    }
    tx.commit().await?;
    Ok(Json(life_event_category_with_types(&state.db, category).await?))
}

