/// The operations of this module.
pub fn routes() -> OpenApiRouter<AppState> {
    OpenApiRouter::new()
        .routes(routes!(list_vault_labels, create_vault_label))
        .routes(routes!(update_vault_label, delete_vault_label))
        .routes(routes!(list_vault_tags, create_vault_tag))
        .routes(routes!(update_vault_tag, delete_vault_tag))
        .routes(routes!(list_vault_contact_important_date_types, create_vault_contact_important_date_type))
        .routes(routes!(update_vault_contact_important_date_type, delete_vault_contact_important_date_type))
        .routes(routes!(list_vault_mood_tracking_parameters, create_vault_mood_tracking_parameter))
        .routes(routes!(update_vault_mood_tracking_parameter, delete_vault_mood_tracking_parameter))
        .routes(routes!(list_vault_life_event_categories, create_vault_life_event_category))
        .routes(routes!(update_vault_life_event_category, delete_vault_life_event_category))
        .routes(routes!(create_vault_life_event_type))
        .routes(routes!(update_vault_life_event_type, delete_vault_life_event_type))
        .routes(routes!(list_vault_quick_fact_templates, create_vault_quick_fact_template))
        .routes(routes!(update_vault_quick_fact_template, delete_vault_quick_fact_template))
}
